<script setup lang="ts">
import { computed,onBeforeUnmount,onMounted,reactive,ref,shallowRef } from 'vue'
import { validSession,type Session } from './compensationDTO'
import { FinancialFailure,financialJSON,type FinancialCommand } from './compensationAPI'
import { permitted,validBonusResult,validBonusView,type BonusResult,type BonusView } from './bonusDTO'
const emit=defineEmits<{'session-expired':[]}>()
const employee=ref(''),session=shallowRef<Session|null>(null),view=shallowRef<BonusView|null>(null),error=ref(''),notice=ref(''),busy=ref(false),confirmed=ref(false),pageCursor=ref('')
const query=reactive({from:'',to:'',kind:'',limit:'50'}), target=reactive({from:'',to:'',basis:'annual_plan',currency:'USD',scale:'2',minor:'',reason:''}), award=reactive({target:'',corrects:'',from:'',to:'',category:'performance',currency:'USD',scale:'2',minor:'',reason:''}), payment=reactive({kind:'payment',award:'',original:'',source:'',external:'',date:'',currency:'USD',scale:'2',minor:'',evidence:'',reason:''}), extension=reactive({supersedes:'',memo:'',source:''}), transitionReason=ref('MANUAL_REVIEW')
let alive=false,generation=0,controller:AbortController|null=null,timer=0
const capabilities=computed(()=>new Set(view.value?.permissions.map(p=>p.capability)??[]))
function active(operation:number){return alive&&operation===generation&&!controller?.signal.aborted}
function resetForms(){Object.assign(target,{from:'',to:'',basis:'annual_plan',currency:'USD',scale:'2',minor:'',reason:''});Object.assign(award,{target:'',corrects:'',from:'',to:'',category:'performance',currency:'USD',scale:'2',minor:'',reason:''});Object.assign(payment,{kind:'payment',award:'',original:'',source:'',external:'',date:'',currency:'USD',scale:'2',minor:'',evidence:'',reason:''});Object.assign(extension,{supersedes:'',memo:'',source:''});transitionReason.value='MANUAL_REVIEW'}
function clear(){view.value=null;session.value=null;confirmed.value=false;notice.value='';pageCursor.value='';resetForms()}
function fail(cause:unknown){const status=cause instanceof FinancialFailure?cause.status:503;clear();if(status===401)emit('session-expired');error.value=[401,403,404].includes(status)?'会话、MFA、purpose、scope 或授权失效；奖金事实与表单确认已销毁。':status===409?'版本已变化；不会自动重试。请重载后重新核对。':status===422?'输入不符合奖金领域约束。':'结果未确认；不显示成功，不自动重发。'}
async function load(expected?:Session){generation++;controller?.abort();controller=new AbortController();const operation=generation;busy.value=true;error.value='';notice.value='';try{const current=await financialJSON<Session>('/session',controller.signal,()=>active(operation));if(!validSession(current)||expected&&(current.subject_id!==expected.subject_id||current.auth_epoch!==expected.auth_epoch))throw new FinancialFailure(403);session.value=current;const params=new URLSearchParams({limit:query.limit});if(query.from)params.set('period_start',query.from);if(query.to)params.set('period_end',query.to);if(query.kind)params.set('record_kind',query.kind);if(pageCursor.value)params.set('cursor',pageCursor.value);const next=await financialJSON<BonusView>(`/employees/${employee.value}/bonuses?${params}`,controller.signal,()=>active(operation)&&session.value===current);if(!validBonusView(next,employee.value)||Date.parse(next.authorization_until)<=Date.now())throw new FinancialFailure(503);view.value=next}catch(cause){if(active(operation))fail(cause)}finally{if(active(operation))busy.value=false}}
async function command(path:string,capability:string,body:unknown,method:'POST'|'PATCH'='POST'){if(busy.value||!session.value||!view.value||!permitted(session.value,view.value,capability)||!confirmed.value)return;const context=session.value;generation++;controller?.abort();controller=new AbortController();const operation=generation;busy.value=true;error.value='';notice.value='';try{const current=await financialJSON<Session>('/session',controller.signal,()=>active(operation)&&session.value===context);if(!validSession(current)||current.subject_id!==context.subject_id||current.auth_epoch!==context.auth_epoch)throw new FinancialFailure(403);const request:FinancialCommand={path,method,body:JSON.stringify(body),key:crypto.randomUUID(),context:current,capability,exporting:false};const result=await financialJSON<BonusResult>(path,controller.signal,()=>active(operation)&&session.value===context,request,current.csrf_token);if(!validBonusResult(result))throw new FinancialFailure(503);view.value=null;confirmed.value=false;pageCursor.value='';resetForms();busy.value=false;await load(current);if(view.value)notice.value='命令已提交，并从服务器重载最新奖金事实。'}catch(cause){if(active(operation))fail(cause)}finally{if(active(operation))busy.value=false}}
function applyQuery(){pageCursor.value='';void load()}
function nextPage(){if(view.value?.next_cursor){pageCursor.value=view.value.next_cursor;void load(session.value??undefined)}}
function createTarget(){void command(`/employees/${employee.value}/bonus-targets`,'bonus.target.manage',{period_start:target.from,period_end:target.to,bonus_revision:view.value?.bonus_revision,initial_state:'confirmed',target:{basis:target.basis,amount:{currency:target.currency,scale:Number(target.scale),amount_minor:target.minor},reason:target.reason}})}
function transitionTarget(id:string,revision:string,action:string){void command(`/bonus-targets/${id}/transitions`,'bonus.target.manage',{action,revision,bonus_revision:view.value?.bonus_revision,reason:transitionReason.value})}
function createAward(){void command(`/employees/${employee.value}/bonus-awards`,'bonus.propose',{bonus_revision:view.value?.bonus_revision,target_id:award.target||null,corrects_award_id:award.corrects||null,award:{period_start:award.from,period_end:award.to,category:award.category,reason:award.reason,amount:{currency:award.currency,scale:Number(award.scale),amount_minor:award.minor}}})}
function editAward(item:BonusView['awards'][number]){void command(`/bonus-awards/${item.id}`,'bonus.propose',{revision:item.revision,bonus_revision:view.value?.bonus_revision,target_id:award.target||item.target_id,corrects_award_id:award.corrects||item.corrects_award_id,award:{period_start:award.from||item.award.period_start,period_end:award.to||item.award.period_end,category:award.category||item.award.category,reason:award.reason||item.award.reason,amount:{currency:award.currency||item.award.amount.currency,scale:award.minor?Number(award.scale):item.award.amount.scale,amount_minor:award.minor||item.award.amount.amount_minor}}},'PATCH')}
function transitionAward(id:string,revision:string,action:string){void command(`/bonus-awards/${id}/transitions`,action==='approve'||action==='reject'?'bonus.approve':'bonus.propose',{action,revision,bonus_revision:view.value?.bonus_revision,decision_reason:action==='approve'||action==='reject'?transitionReason.value:''})}
function recordPayment(){void command(`/employees/${employee.value}/bonus-payments`,'bonus.payment.record',{bonus_revision:view.value?.bonus_revision,business_source:payment.source,external_fact_id:payment.external,kind:payment.kind,paid_date:payment.date,evidence_reference:payment.evidence,reason:payment.reason,amount:{currency:payment.currency,scale:Number(payment.scale),amount_minor:payment.minor},award_id:payment.award||null,original_payment_id:payment.original||null})}
function addExtension(){void command(`/employees/${employee.value}/compensation/extensions`,'compensation.extension.manage',{comp_revision:view.value?.comp_revision,schema_type:'compensation_memo/v1',schema_version:1,supersedes_id:extension.supersedes||null,payload:{memo:extension.memo,source_reference:extension.source||undefined}})}
function route(){const match=/^\/employees\/([0-9a-f-]+)\/bonuses\/?$/.exec(location.pathname);clear();employee.value=match?.[1]??'';if(employee.value)void load()}
onMounted(()=>{alive=true;addEventListener('popstate',route);timer=window.setInterval(()=>{if(view.value&&Date.parse(view.value.authorization_until)<=Date.now())fail(new FinancialFailure(403))},1000);route()});onBeforeUnmount(()=>{alive=false;removeEventListener('popstate',route);clearInterval(timer);controller?.abort();clear()})
</script>
<template><main><header><p class="eyebrow">P-BONUS-01</p><h1>奖金控制台</h1><p>员工 <code>{{employee}}</code> · 独立目标、奖励、批准、支付与扩展边界</p></header><p v-if="error" role="alert" class="error">{{error}}</p><p v-if="notice" role="status" class="notice">{{notice}}</p>
<section><h2>范围与对账</h2><form @submit.prevent="applyQuery"><label>开始<input v-model="query.from" type="date"></label><label>结束<input v-model="query.to" type="date"></label><label>记录类型<select v-model="query.kind"><option value="">全部（单列超上限时请选择具体类型）</option><option>targets</option><option>awards</option><option>payments</option><option>extensions</option></select></label><label>上限<input v-model="query.limit" inputmode="numeric"></label><button :disabled="busy">重载</button></form><p v-if="view">奖金版本 R{{view.bonus_revision}} · 薪酬版本 R{{view.comp_revision}} · 授权至 {{view.authorization_until}}</p><button v-if="view?.next_cursor" :disabled="busy" @click="nextPage">下一页</button><table v-if="view?.balances.length"><caption>已批准、已支付与余额</caption><thead><tr><th>奖励</th><th>币种</th><th>批准</th><th>支付</th><th>余额</th><th>状态</th></tr></thead><tbody><tr v-for="row in view.balances" :key="row.effective_award_id"><td><code>{{row.effective_award_id}}</code></td><td>{{row.currency}}/{{row.scale}}</td><td>{{row.approved_minor}}</td><td>{{row.paid_minor}}</td><td>{{row.balance_minor}}</td><td>{{row.payment_state}}</td></tr></tbody></table><ul class="anomaly"><li v-for="item in view?.anomalies" :key="item.kind+item.payment_id">异常：{{item.kind}} · {{item.payment_id}}<template v-if="item.award_id"> · {{item.award_id}}</template></li></ul></section>
<section><h2>目标清单</h2><article v-for="item in view?.targets" :key="item.id"><strong>{{item.state}} · {{item.target.amount.amount_minor}} {{item.target.amount.currency}}/{{item.target.amount.scale}}</strong><code>{{item.id}}</code><button v-if="item.state==='draft'&&capabilities.has('bonus.target.manage')" :disabled="busy||!confirmed" @click="transitionTarget(item.id,item.revision,'confirm')">确认</button><button v-if="item.state!=='withdrawn'&&capabilities.has('bonus.target.manage')" :disabled="busy||!confirmed" @click="transitionTarget(item.id,item.revision,'withdraw')">撤回</button></article><form v-if="capabilities.has('bonus.target.manage')" @submit.prevent="createTarget"><input v-model="target.from" aria-label="目标开始" type="date" required><input v-model="target.to" aria-label="目标结束" type="date" required><input v-model="target.basis" aria-label="目标口径" required><input v-model="target.currency" aria-label="目标币种" required><input v-model="target.scale" aria-label="目标精度" required><input v-model="target.minor" aria-label="目标最小单位金额" required><input v-model="target.reason" aria-label="目标理由" required><button :disabled="busy||!confirmed">创建已确认目标</button></form></section>
<section v-if="capabilities.has('bonus.propose')"><h2>奖励草稿</h2><form @submit.prevent="createAward"><input v-model="award.target" aria-label="目标 ID"><input v-model="award.corrects" aria-label="被纠正奖励 ID"><input v-model="award.from" aria-label="奖励开始" type="date" required><input v-model="award.to" aria-label="奖励结束" type="date" required><input v-model="award.category" aria-label="奖励类别" required><input v-model="award.currency" aria-label="奖励币种" required><input v-model="award.scale" aria-label="奖励精度" required><input v-model="award.minor" aria-label="奖励最小单位金额" required><input v-model="award.reason" aria-label="奖励理由" required><button :disabled="busy||!confirmed">创建草稿奖励</button></form></section>
<section><h2>奖励清单</h2><label v-if="capabilities.has('bonus.propose')||capabilities.has('bonus.approve')">转换/决定理由<input v-model="transitionReason" aria-label="转换决定理由"></label><article v-for="item in view?.awards" :key="item.id"><strong>{{item.state}} · {{item.award.amount.amount_minor}} {{item.award.amount.currency}}/{{item.award.amount.scale}}</strong><code>{{item.id}}</code><button v-if="item.state==='draft'&&capabilities.has('bonus.propose')" :disabled="busy||!confirmed" @click="editAward(item)">按上方非空字段修改</button><button v-if="item.state==='draft'&&capabilities.has('bonus.propose')" :disabled="busy||!confirmed" @click="transitionAward(item.id,item.revision,'submit')">提交</button><button v-if="(item.state==='draft'||item.state==='submitted')&&capabilities.has('bonus.propose')" :disabled="busy||!confirmed" @click="transitionAward(item.id,item.revision,'withdraw')">撤回</button><button v-if="item.state==='submitted'&&capabilities.has('bonus.approve')&&item.author_subject_id!==session?.subject_id" :disabled="busy||!confirmed" @click="transitionAward(item.id,item.revision,'approve')">批准</button><button v-if="item.state==='submitted'&&capabilities.has('bonus.approve')" :disabled="busy||!confirmed" @click="transitionAward(item.id,item.revision,'reject')">拒绝</button></article></section>
<section><h2>支付与冲销事实</h2><article v-for="item in view?.payments" :key="item.id"><strong>{{item.kind}} · {{item.amount.amount_minor}} {{item.amount.currency}}/{{item.amount.scale}} · {{item.paid_date}}</strong><code>{{item.id}}</code><span v-if="item.anomalies.length" class="anomaly">{{item.anomalies.join('、')}}</span></article><form v-if="capabilities.has('bonus.payment.record')" @submit.prevent="recordPayment"><select v-model="payment.kind" aria-label="支付类型"><option value="payment">payment</option><option value="reversal">reversal</option></select><input v-model="payment.award" aria-label="奖励 ID"><input v-model="payment.original" aria-label="原支付 ID"><input v-model="payment.source" aria-label="受控来源" required><input v-model="payment.external" aria-label="外部事实 ID" required><input v-model="payment.date" aria-label="支付日期" type="date" required><input v-model="payment.currency" aria-label="支付币种" required><input v-model="payment.scale" aria-label="支付精度" required><input v-model="payment.minor" aria-label="支付最小单位金额" required><input v-model="payment.evidence" aria-label="证据引用" required><input v-model="payment.reason" aria-label="支付理由" required><button :disabled="busy||!confirmed">记录支付/冲销事实</button></form></section>
<section><h2>有限扩展</h2><form v-if="capabilities.has('compensation.extension.manage')" @submit.prevent="addExtension"><input v-model="extension.supersedes" aria-label="被替代扩展 ID"><textarea v-model="extension.memo" aria-label="扩展备忘" required></textarea><input v-model="extension.source" aria-label="来源引用"><button :disabled="busy||!confirmed">追加扩展事实</button></form><ul><li v-for="item in view?.extensions" :key="item.id">{{item.payload.memo}} · R{{item.revision}}<template v-if="item.supersedes_id"> · 替代 {{item.supersedes_id}}</template></li></ul></section><label class="confirm"><input v-model="confirmed" type="checkbox">我已按最新 R{{view?.bonus_revision}} 核对命令、对象、金额、日期、理由与证据；每个按钮只提交一个独立命令。</label></main></template>
<style scoped>main{max-width:76rem;margin:auto;padding:1rem;font-family:system-ui;color:#17212b}header,section{border:1px solid #ccd6df;border-radius:.7rem;padding:1rem;margin:1rem 0;background:#fff}.eyebrow{font-weight:800;color:#176553}form{display:flex;flex-wrap:wrap;gap:.7rem;align-items:end}label{display:grid;gap:.25rem}input,select,textarea,button{font:inherit;padding:.5rem;border:1px solid #8ba0b2;border-radius:.35rem}button{background:#176553;color:white;border:0;font-weight:700}button:disabled{opacity:.45}table{border-collapse:collapse;width:100%}th,td{padding:.45rem;border-bottom:1px solid #dce3e8;text-align:left}.error,.anomaly{color:#9b1c1c}.notice{color:#17653a}article{display:flex;gap:1rem;align-items:center;padding:.5rem 0}.confirm{position:sticky;bottom:0;background:#fff4ce;border:1px solid #d6a900;padding:.8rem}</style>
